1	package clusterdata.query;
2	
3	import clusterdata.datatypes.JobEvent;
4	import clusterdata.datatypes.TaskEvent;
5	import clusterdata.utils.AppBase;
6	import org.apache.flink.api.common.functions.FilterFunction;
7	import org.apache.flink.api.common.state.ValueState;
8	import org.apache.flink.api.common.state.ValueStateDescriptor;
9	import org.apache.flink.api.java.tuple.Tuple2;
10	import org.apache.flink.api.java.utils.ParameterTool;
11	import org.apache.flink.configuration.Configuration;
12	import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
13	import org.apache.flink.streaming.api.functions.KeyedProcessFunction;
14	import org.apache.flink.streaming.api.functions.sink.SinkFunction;
15	import org.apache.flink.streaming.api.functions.source.SourceFunction;
16	import org.apache.flink.streaming.api.functions.windowing.WindowFunction;
17	import org.apache.flink.streaming.api.watermark.Watermark;
18	import org.apache.flink.streaming.api.windowing.assigners.EventTimeSessionWindows;
19	import org.apache.flink.streaming.api.windowing.time.Time;
20	import org.apache.flink.streaming.api.windowing.windows.TimeWindow;
21	import org.apache.flink.util.Collector;
22	
23	import java.io.BufferedWriter;
24	import java.io.FileWriter;
25	import java.io.IOException;
26	import java.io.Serializable;
27	
28	public class LongestSessionPerJob extends AppBase {
29	
30	    public static class GzipCsvSource implements SourceFunction<TaskEvent> {
31	        private final String filePath;
32	        private volatile boolean running = true;
33	
34	        public GzipCsvSource(String filePath) {
35	            this.filePath = filePath;
36	        }
37	
38	        @Override
39	        public void run(SourceContext<TaskEvent> ctx) throws Exception {
40	            try (java.util.zip.GZIPInputStream gis = new java.util.zip.GZIPInputStream(
41	                    new java.io.FileInputStream(filePath));
42	                 java.io.BufferedReader br = new java.io.BufferedReader(
43	                         new java.io.InputStreamReader(gis))) {
44	                String line;
45	                while ((line = br.readLine()) != null && running) {
46	                    try {
47	                        TaskEvent event = TaskEvent.fromCsvLine(line);
48	                        ctx.collectWithTimestamp(event, event.timestamp);
49	                    } catch (Exception e) {
50	                        // Skip malformed lines
51	                    }
52	                }
53	            }
54	        }
55	
56	        @Override
57	        public void cancel() {
58	            running = false;
59	        }
60	    }
61	
62	    public static class TaskEventTimestampExtractor implements org.apache.flink.streaming.api.functions.AssignerWithPeriodicWatermarks<TaskEvent> {
63	        private long maxTimestamp = Long.MIN_VALUE;
64	
65	        @Override
66	        public long extractTimestamp(TaskEvent element, long previousElementTimestamp) {
67	            maxTimestamp = Math.max(maxTimestamp, element.timestamp);
68	            return element.timestamp;
69	        }
70	
71	        @Override
72	        public Watermark getCurrentWatermark() {
73	            return new Watermark(maxTimestamp == Long.MIN_VALUE ? 0 : maxTimestamp - 1);
74	        }
75	    }
76	
77	    public static class StageWindowFunction implements WindowFunction<TaskEvent, Tuple2<Long, Integer>, Long, TimeWindow> {
78	        @Override
79	        public void apply(Long jobId, TimeWindow window, Iterable<TaskEvent> events, Collector<Tuple2<Long, Integer>> out) {
80	            int count = 0;
81	            for (TaskEvent e : events) {
82	                count++;
83	            }
84	            if (count > 0) {
85	                out.collect(new Tuple2<>(jobId, count));
86	            }
87	        }
88	    }
89	
90	    public static class MaxStageFinder extends KeyedProcessFunction<Long, Tuple2<Long, Integer>, Tuple2<Long, Integer>> {
91	        private ValueState<Integer> maxStageSize;
92	
93	        @Override
94	        public void open(Configuration parameters) {
95	            maxStageSize = getRuntimeContext().getState(
96	                    new ValueStateDescriptor<>("maxStageSize", Integer.class));
97	        }
98	
99	        @Override
100	        public void processElement(Tuple2<Long, Integer> stageInfo, Context ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
101	            Integer current = maxStageSize.value();
102	            int stageSize = stageInfo.f1;
103	            if (current == null || stageSize > current) {
104	                maxStageSize.update(stageSize);
105	                out.collect(new Tuple2<>(stageInfo.f0, stageSize));
106	            }
107	        }
108	    }
109	
110	    public static class FileSink implements SinkFunction<Tuple2<Long, Integer>>, Serializable {
111	        private final String outputPath;
112	
113	        public FileSink(String outputPath) {
114	            this.outputPath = outputPath;
115	        }
116	
117	        @Override
118	        public void invoke(Tuple2<Long, Integer> value, Context context) throws Exception {
119	            if (outputPath != null) {
120	                synchronized (this) {
121	                    try (BufferedWriter writer = new BufferedWriter(new FileWriter(outputPath, true))) {
122	                        writer.write("(" + value.f0 + "," + value.f1 + ")\n");
123	                    }
124	                }
125	            }
126	        }
127	    }
128	
129	    public static void main(String[] args) throws Exception {
130	        ParameterTool params = ParameterTool.fromArgs(args);
131	        String taskInput = params.get("task_input", null);
132	        String jobInput = params.get("job_input", null);
133	        String outputPath = params.get("output", null);
134	        System.out.println("task_input  " + taskInput);
135	        System.out.println("job_input  " + jobInput);
136	        long sesssize = params.getLong("sesssize", 600);
137	
138	        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
139	        env.setParallelism(1);
140	
141	        var taskStream = env.addSource(taskSourceOrTest(new GzipCsvSource(taskInput)))
142	                .assignTimestampsAndWatermarks(new TaskEventTimestampExtractor());
143	
144	        var submitEvents = taskStream
145	                .filter(new FilterFunction<TaskEvent>() {
146	                    @Override
147	                    public boolean filter(TaskEvent event) {
148	                        return event.eventType == 0;
149	                    }
150	                });
151	
152	        var stagesWithCounts = submitEvents
153	                .keyBy((TaskEvent e) -> e.jobId)
154	                .window(EventTimeSessionWindows.withGap(Time.seconds(sesssize)))
155	                .apply(new StageWindowFunction());
156	
157	        var results = stagesWithCounts
158	                .keyBy((Tuple2<Long, Integer> t) -> t.f0)
159	                .process(new MaxStageFinder());
160	
161	        @SuppressWarnings("unchecked")
162	        SinkFunction<Tuple2<Long, Integer>> sink = (SinkFunction<Tuple2<Long, Integer>>) sinkOrTest(new FileSink(outputPath));
163	        results.addSink(sink);
164	
165	        env.execute("LongestSessionPerJob");
166	    }
167	}
